export const villages: string[] = Object.keys(villageToCommune);

/**
 * Kobo serializes a select_multiple answer as a single space-separated string of choice codes
 * (e.g. "1020101 1020104 1020109"). The flood form's "g2/village" question ("which villages were
 * affected?", cascade-filtered by commune) is one such field. This parses that raw string into
 * the list of village codes it represents, dropping any code that isn't in the known choices list
 * (e.g. stale/typo'd codes from an older form version).
 */
export const parseAffectedVillageCodes = (rawFieldValue: string | undefined): string[] => {
  if (rawFieldValue === undefined || rawFieldValue.trim() === '') {
    return [];
  }

  return rawFieldValue
    .trim()
    .split(/\s+/)
    .filter((code) => code in villageToCommune);
};
